// Fail-closed configuration. No secrets are defaulted; local secrets are generated by scripts/setup-local.mjs.
export interface Config {
  databaseUrl: string;       // ts_app role
  redisUrl: string;
  participantPort: number;
  tls: { cert: string; key: string; participantCa: string };
  issuer: string;
  audience: string;
  tokenEndpoint: string;
  kmsDir: string;
  auditSinkPath: string;
  telcoAllowList: string[];  // exact origins only
  telcoTimeoutMs: number;
  requestSkewSeconds: number;
  rateLimitPerSecond: number;      // per client certificate, all routes
  tokenRateLimitPerSecond: number; // per client certificate, token endpoint
}
function need(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`missing required configuration ${name}`);
  return v;
}
export function loadConfig(env = process.env): Config {
  void env;
  return {
    databaseUrl: need("TS_DATABASE_URL"),
    redisUrl: need("TS_REDIS_URL"),
    participantPort: Number(process.env["TS_PARTICIPANT_PORT"] ?? 8443),
    tls: { cert: need("TS_TLS_CERT"), key: need("TS_TLS_KEY"), participantCa: need("TS_PARTICIPANT_CA") },
    issuer: need("TS_ISSUER"),
    audience: process.env["TS_AUDIENCE"] ?? "telco-signal-api",
    tokenEndpoint: need("TS_TOKEN_ENDPOINT"),
    kmsDir: need("TS_KMS_DIR"),
    auditSinkPath: need("TS_AUDIT_SINK"),
    telcoAllowList: need("TS_TELCO_ALLOWLIST").split(",").map((s) => s.trim()).filter(Boolean),
    telcoTimeoutMs: Number(process.env["TS_TELCO_TIMEOUT_MS"] ?? 2000),
    requestSkewSeconds: Number(process.env["TS_REQUEST_SKEW_SECONDS"] ?? 60),
    rateLimitPerSecond: Number(process.env["TS_RATE_LIMIT_RPS"] ?? 100),
    tokenRateLimitPerSecond: Number(process.env["TS_TOKEN_RATE_LIMIT_RPS"] ?? 10),
  };
}
